package org.pocketsurf.browser

import android.content.Intent
import android.graphics.Rect
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.os.Looper
import android.os.SystemClock
import android.view.*
import android.webkit.WebView
import android.widget.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config
import java.time.Duration

/** Native layout and bridge-contract fixtures. These do not execute a real Chromium renderer. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi",shadows=[RecordingWebViewShadow::class])
class HandheldUxRegressionTest {
 @org.junit.Before fun skipFirstRunForBrowserFixture(){org.robolectric.RuntimeEnvironment.getApplication().getSharedPreferences("browser",0).edit().putBoolean("setup_complete",true).commit()}
 @Before fun clear(){RecordingWebViewShadow.clearEvidence()}
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun views(a:BrowserActivity)=all(a.window.decorView)
 private fun desc(a:BrowserActivity,s:String)=views(a).filter{it.contentDescription?.toString()==s}.let{it.firstOrNull{v->v.isShown}?:it.first()}
 private fun label(a:BrowserActivity,s:String)=views(a).filterIsInstance<TextView>().firstOrNull{it.text.toString()==s}
 private fun settle(a:BrowserActivity){a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)};TestFrameClock.advance(Duration.ofMillis(if(views(a).any{it.contentDescription?.toString()?.endsWith(" popup")==true})360 else 16));a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)}}
 private fun start(url:String?=null)=Robolectric.buildActivity(BrowserActivity::class.java,Intent().apply{url?.let{data=Uri.parse(it)}}).setup().visible().also{settle(it.get())}
 private fun key(a:BrowserActivity,k:Int){a.dispatchKeyEvent(KeyEvent(0,k));a.dispatchKeyEvent(KeyEvent(1,k));settle(a)}
 private fun click(a:BrowserActivity,s:String){if(BrowserTestActions.settingsClick(a,s))return;if(s=="History"){if(views(a).any{it.contentDescription=="Menu popup"})key(a,97);desc(a,"History").performClick();settle(a);return};var v:View=views(a).firstOrNull{it.isShown&&it.hasOnClickListeners()&&it.contentDescription==s}?:label(a,s)?:desc(a,s);while(!v.hasOnClickListeners())v=v.parent as View;v.performClick();settle(a)}
 private fun address(a:BrowserActivity)=views(a).filterIsInstance<EditText>().first{it.contentDescription?.startsWith("Address or")==true}
 private fun motion(axis:Int,value:Float):MotionEvent{val p=MotionEvent.PointerProperties().apply{id=0};val c=MotionEvent.PointerCoords().apply{setAxisValue(axis,value)};return MotionEvent.obtain(0,0,MotionEvent.ACTION_MOVE,1,arrayOf(p),arrayOf(c),0,0,1f,1f,0,0,InputDevice.SOURCE_JOYSTICK,0)}
 private fun touch(a:BrowserActivity,target:View){val rect=Rect();assertTrue(target.getGlobalVisibleRect(rect));val now=SystemClock.uptimeMillis();for(action in listOf(MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP)){val e=MotionEvent.obtain(now,now+10,action,rect.exactCenterX(),rect.exactCenterY(),0);e.source=InputDevice.SOURCE_TOUCHSCREEN;a.dispatchTouchEvent(e);e.recycle()};settle(a)}
 @Test fun browserChromeUsesAtMost128dpExcludingSystemInsets(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();val root=web.parent as View;val browser=(root.parent as View).parent as View;val available=browser.height-browser.paddingTop-browser.paddingBottom;assertTrue("Chrome consumes more than128dp",available-root.height<=128);assertTrue("Page must retain most of the usable area",root.height>=available*.7f);val xy=IntArray(2);address(a).getLocationOnScreen(xy);val webXY=IntArray(2);web.getLocationOnScreen(webXY);assertTrue("Address must precede page",xy[1]+address(a).height<=webXY[1]);c.pause().stop().destroy()}
 @Test fun settingsGearIsVisibleAndMenuContainsNoSettingsAction(){val c=start();val a=c.get();val logo=desc(a,"Settings");assertTrue(logo.isShown);assertTrue(all(logo).filterIsInstance<ImageView>().isNotEmpty());assertTrue(all(logo).filterIsInstance<TextView>().none{it.text=="Settings"});key(a,109);val overlay=views(a).filterIsInstance<TextView>().first{it.text=="Menu"}.parent as View;assertTrue(all(overlay).filterIsInstance<TextView>().none{it.text=="Settings"});key(a,97);touch(a,logo);assertNotNull(label(a,"Appearance & accessibility"));for(s in listOf("Browsing","Privacy & protection","About & help"))assertNotNull(label(a,s));c.pause().stop().destroy()}
 @Test fun aSingleTouchExecutesAndChangesInputMode(){val c=start();val a=c.get();touch(a,desc(a,"Menu"));assertNotNull(label(a,"Menu"));val legend=views(a).filterIsInstance<HorizontalScrollView>().last();assertEquals(View.VISIBLE,legend.visibility);assertTrue(legend.contentDescription.toString().startsWith("Touch controls:"));key(a,97);assertEquals(View.VISIBLE,legend.visibility);assertTrue(legend.contentDescription.toString().startsWith("Controller controls:"));assertTrue(views(a).none{it.contentDescription=="Menu popup"});assertEquals(6,views(a).count{it.contentDescription?.startsWith("Pin bookmark ")==true});touch(a,desc(a,"Pin bookmark 1"));assertNotNull(label(a,"Enter a website"));c.pause().stop().destroy()}
 @Test fun topTabsAreTouchOnlyAndOnlyCurrentCloseIsShown(){val c=start("https://fixture.test");val a=c.get();BrowserTestActions.newTab(a);assertSame(address(a),a.window.decorView.findFocus());key(a,19);assertFalse(a.window.decorView.findFocus()?.contentDescription?.startsWith("Tab 2:")==true);desc(a,"Close New tab").performClick();settle(a);assertEquals(1,views(a).count{it.contentDescription?.startsWith("Tab ")==true});assertEquals("https://fixture.test",views(a).filterIsInstance<WebView>().single().url);c.pause().stop().destroy()}
 @Test fun browserPopupKeepsThePageAttachedAndBlocksShoulders(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();key(a,109);assertSame(web,views(a).filterIsInstance<WebView>().single());RecordingWebViewShadow.clearEvidence();key(a,102);key(a,103);val e=motion(MotionEvent.AXIS_RZ,1f);a.dispatchGenericMotionEvent(e);e.recycle();TestFrameClock.advance(Duration.ofMillis(100));assertTrue(RecordingWebViewShadow.scripts.none{it.contains(".move(")||it.contains(".setScroll(")&&!it.contains(".setScroll(0.0,0.0)")});assertNotNull(label(a,"Menu"));key(a,97);assertSame(web,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}
 @Test fun heldConfirmAddsContextOptionsToTheBrowserMenu(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();a.dispatchKeyEvent(KeyEvent(0,96));Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));a.dispatchKeyEvent(KeyEvent(1,96));val shadow=Shadows.shadowOf(web);assertTrue(shadow.lastEvaluatedJavascript.contains(".target()"));shadow.lastEvaluatedJavascriptCallback.onReceiveValue(JSONObject.quote("""{"link":"https://destination.test","title":"Fixture link","rect":{"left":30,"top":40,"width":100,"height":30},"viewportWidth":960}"""));settle(a);assertSame(web,views(a).filterIsInstance<WebView>().single());assertNotNull(label(a,"Menu"));assertTrue(views(a).filterIsInstance<TextView>().any{it.text.contains("Fixture link")});assertNotNull(label(a,"Open in new tab"));assertTrue(views(a).any{it.contentDescription=="Menu popup"});key(a,97);assertSame(web,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}
 @Test fun baseThemesAndAccentChoicesAreVisibleWithoutScrolling(){val c=start();val a=c.get();click(a,"Settings");click(a,"Appearance");val colors=mutableSetOf<Int>();for(name in BrowserTheme.names){val card=desc(a,"$name theme") as ViewGroup;val rect=Rect();assertTrue("$name hidden",card.getGlobalVisibleRect(rect));assertTrue("$name vertically clipped",rect.height()>=card.height-1);val preview=card.getChildAt(0);val expected=BrowserTheme.resolve(name,a.resources.configuration.uiMode and android.content.res.Configuration.UI_MODE_NIGHT_MASK==android.content.res.Configuration.UI_MODE_NIGHT_YES);assertEquals(expected.background,(preview.background as GradientDrawable).color!!.defaultColor);colors.add(expected.background)};assertTrue("Themes need distinguishable previews",colors.size>=3);for(name in BrowserTheme.accentNames){val swatch=desc(a,"$name accent");val r=Rect();assertTrue(swatch.getGlobalVisibleRect(r));assertTrue(r.height()>=swatch.height-1)};for(scroll in views(a).filterIsInstance<ScrollView>()){assertEquals(0,scroll.scrollY);assertFalse("Appearance needs vertical scrolling",scroll.canScrollVertically(1))};c.pause().stop().destroy()}
 @Test fun historyClearHasVisibleWordsAndRecentlyClosedHasAnAccessibleIcon(){val c=start();val a=c.get();key(a,109);click(a,"History");assertNotNull(label(a,"Clear history"));assertTrue(desc(a,"Clear history").hasOnClickListeners());key(a,97);BrowserTestActions.openTabs(a);assertTrue(desc(a,"Recently closed tabs").isShown);assertNotNull(label(a,"Recently closed tabs"));c.pause().stop().destroy()}
 @Test fun addressEditStopsHeldControllerAndBackHidesKeyboardThenCancels(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();val e=motion(MotionEvent.AXIS_RZ,1f);a.dispatchGenericMotionEvent(e);e.recycle();TestFrameClock.advance(Duration.ofMillis(50));BrowserTestActions.focusAddress(a);key(a,96);val field=address(a);field.setText("unsent words");RecordingWebViewShadow.clearEvidence();TestFrameClock.advance(Duration.ofMillis(500));assertTrue(RecordingWebViewShadow.scripts.none{it.contains(".move(")||it.contains(".setScroll(")&&!it.contains(".setScroll(0.0,0.0)")});assertSame(field,a.window.decorView.findFocus());assertEquals("unsent words",field.text.toString());assertSame(web,views(a).filterIsInstance<WebView>().single());assertTrue(desc(a,"Go").isShown);key(a,97);assertTrue("First Back must keep editing",desc(a,"Go").isShown);assertEquals("unsent words",field.text.toString());key(a,97);assertEquals(View.VISIBLE,desc(a,"Go").visibility);assertFalse(desc(a,"Go").isEnabled);assertEquals("https://fixture.test",web.url);assertFalse(a.isFinishing);c.pause().stop().destroy()}
 @Test fun closingUsesUndoRatherThanAConfirmation(){val c=start("https://fixture.test");val a=c.get();BrowserTestActions.openTabs(a);desc(a,"Current tab: fixture.test").requestFocus();key(a,99);assertNotNull(label(a,"0 tabs · choose a page to continue"));assertNull(label(a,"Cancel"));click(a,"Undo");assertTrue(views(a).any{it.contentDescription=="Current tab: fixture.test"});c.pause().stop().destroy()}
 @Test fun webEditableActivationStopsFurtherNavigationUntilBack(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();val shadow=Shadows.shadowOf(web);BrowserActivity::class.java.getDeclaredMethod("activateElement").apply{isAccessible=true}.invoke(a);assertTrue(shadow.lastEvaluatedJavascript.contains(".activationPoint()"));shadow.lastEvaluatedJavascriptCallback.onReceiveValue("{\"x\":10,\"y\":10,\"width\":960,\"editable\":true}");RecordingWebViewShadow.clearEvidence();val e=motion(MotionEvent.AXIS_Y,1f);a.dispatchGenericMotionEvent(e);e.recycle();TestFrameClock.advance(Duration.ofMillis(250));assertTrue(RecordingWebViewShadow.scripts.none{it.contains(".move(")});key(a,97);assertEquals("https://fixture.test",web.url);assertTrue(RecordingWebViewShadow.scripts.any{it.contains(".releaseEditing()")});c.pause().stop().destroy()}
 @Test fun touchingChromeWhileAPopupIsOpenOnlyDismissesIt(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();key(a,109);touch(a,desc(a,"Settings"));TestFrameClock.advance(Duration.ofMillis(360));settle(a);assertFalse(views(a).any{it.contentDescription=="Menu popup"});assertNull(label(a,"Appearance"));assertSame(web,views(a).filterIsInstance<WebView>().single());assertFalse("Restored chrome must adopt touch-mode focusability",desc(a,"Settings").isFocusableInTouchMode);touch(a,desc(a,"Settings"));assertNotNull(label(a,"Appearance & accessibility"));c.pause().stop().destroy()}
 @Test fun headerTabCloseDoesNotRequireAContextSubmenu(){val c=start();val a=c.get();BrowserTestActions.newTab(a);BrowserTestActions.newTab(a);desc(a,"Close New tab").performClick();settle(a);assertTrue(views(a).none{it.contentDescription=="Menu popup"});assertEquals(1,views(a).count{it.contentDescription?.startsWith("Tab ")==true});c.pause().stop().destroy()}

 @Test fun receivedFaviconPreservesAddressDraftAndFocus(){val c=start("https://fixture.test");val a=c.get();val web=views(a).filterIsInstance<WebView>().single();BrowserTestActions.focusAddress(a);key(a,96);val field=address(a);field.setText("unfinished search");web.webChromeClient!!.onReceivedIcon(web,android.graphics.Bitmap.createBitmap(8,8,android.graphics.Bitmap.Config.ARGB_8888));settle(a);assertSame(field,address(a));assertSame(field,a.window.decorView.findFocus());assertEquals("unfinished search",field.text.toString());assertTrue(desc(a,"Go").isShown);assertSame(web,views(a).filterIsInstance<WebView>().single());c.pause().stop().destroy()}
}
